def transform(grid):
    h,w=len(grid),len(grid[0])
    out=[row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c]==2:
                for rr,cc in ((h-1-r,c),(r,w-1-c),(h-1-r,w-1-c)):
                    if grid[rr][cc]!=2:
                        out[r][c]=grid[rr][cc]
                        break
    return out
